## 6. Visualiser & Main Views

```swift
import SwiftUI

// ──────────────────────────────────────────────
// Simulated Equaliser Visualiser
// Uses deterministic pseudo‑random jitter so bars
// never repeat identically. For true acoustic
// visualisation replace this with a DSP callback.
// ──────────────────────────────────────────────

final class VisualizerEngine: Sendable {
    let bands: [EQBandModel]

    func estimate(at elapsedSeconds: Double) -> [EQEstimate] {
        let n = bands.count
        guard n > 0 else { return repeatElement(EQEstimate(centerHz: 0, level: 0), count: n) }
        var results = [EQEstimate](repeating: EQEstimate(centerHz: 0, level: 0), count: n)

        for i in 0..<n {
            let band = bands[i]
            let freq = Double(band.centerHz) * 0.45
            let t = elapsedSeconds

            // Primary oscillation
            let phase = (freq * t + Double(i) * 2.1) % (2 * .pi)
            let base  = sin(phase)

            // Slow amplitude modulation per band
            let mod   = Sin(t * 3.0 + Double(i) * 0.7) * 0.3

            let amp = (0.2 + 0.6 * abs(base + mod))

            // Deterministic “histórico” jitter
            let jitter = computeJitter(elapsed: t, bandIdx: i) * 0.15

            let level = max(0.0, min(1.0, (amp + jitter) / 1.0))
            results[i] = EQEstimate(centerHz: band.centerHz, level: level)
        }
        return results
    }

    /// Simple MCGR‑based LCG seeded per time/band index
    private func computeJitter(elapsed: Double, bandIdx: Int) -> Double {
        var state: Int64 = Int64(elapsed * 1000 + Double(bandIdx) * 7 + 1234)
        var x = state
        x = (x * 1664525 + 1013904223) & 0xFFFFFFFFFFFFFFFF
        x = (x * 1664525 + 1013904223) & 0xFFFFFFFFFFFFFFFF
        let u = Double((x >> 32) & 0xFFFFFFFF) / Double(Int64.max)
        return u * (2 * .pi)
    }
}

// ──────────────────────────────────────────────
// Animated EQ Bars
// ──────────────────────────────────────────────

struct EquaVisualizationView: View {
    @Bindable var vm: RecordingViewModel

    var body: some View {
        ZStack(alignment: .leading) {
            LinearGradient(colors: [Color.black, Color.gray.opacity(0.3)], startPoint: .topLeading, endPoint: .bottomTrailing)
                .ignoresSafeArea()

            VStack(spacing: 1) {
                ForEach(vm.eqBands.indices) { index in
                    GuardedBar(
                        band: vm.eqBands[index],
                        level: vm.visualEstimates?[index]?.level ?? 0.0
                    )
                }
            }
            .frame(height: 130)
            .shadow(color: .black.opacity(0.5), radius: 10)
        }
        .opacity(vm.isRecording ? 1.0 : 0.4)
        .animation(.easeInOut(duration: 0.3), value: vm.isRecording)
    }
}

struct GuardedBar: View {
    let band: EQBandModel
    let level: Double

    var body: some View {
        ZStack {
            // Glow
            Circle()
                .fill(band.hue.opacity(level * 0.4))
                .frame(width: 12, height: min(12, Int(level * 55)))
                .offset(y: -(min(12, Int(level * 55)) / 2))

            // Track
            Rectangle()
                .fill(Color.white.opacity(0.15))
                .frame(width: 12, height: 4)

            // Active bar
            Rectangle()
                .fill(band.hue.opacity(0.9))
                .frame(width: 12, height: max(4, Int(min(1, level) * 38)))
        }
        .frame(maxWidth: .infinity)
        .rotationEffect(.degrees(band.centerHz * 0.001))
    }
}

// ──────────────────────────────────────────────
// Main Recording Screen
// ──────────────────────────────────────────────

struct RecordingView: View {
    @Bindable var vm: RecordingViewModel

    var body: some View {
        NavigationStack {
            ScrollView {
                VStack(spacing: 20) {

                    // ═══ Live EQ visualisation ═══════
                    EquaVisualizationView(vm: vm)
                        .padding(.horizontal)

                    // ═══ Status ═════════════════════
                    HStack(spacing: 8) {
                        Image(systemName: stateIcon)
                            .font(.title2)
                            .foregroundStyle(stateColor)
                        Text(stateText)
                            .font(.subheadline)
                            .foregroundStyle(.secondary)
                    }
                    .padding(.vertical, 6)

                    if vm.isRecording {
                        ProgressView(value: vm.progress)
                            .progressViewStyle(.determinate)
                            .tint(.cyan)
                            .padding(.top, 4)
                    }

                    Spacer(minLength: 24)

                    // ═══ Control Buttons ════════════
                    HStack(spacing: 20) {
                        if vm.canStop {
                            Button(role: .destructive) {
                                vm.stopRecording()
                            } label: {
                                Label("Recording", systemImage: "microphone.slash.fill")
                                    .frame(maxWidth: .infinity)
                            }
                            .tint(.red)
                        } else {
                            Button(role: .callAction) {
                                vm.startRecording()
                            } label: {
                                Label("Start Recording", systemImage: "microphone.fill")
                            }
                        }

                        if vm.hasCompleted {
                            Button {
                                // In production, open a file picker or share sheet
                            } label: {
                                Label("Done", systemImage: "checkmark.circle.fill")
                            }
                        }
                    }
                    .padding(14)
                    .background(Color.black.opacity(0.2))
                    .clipShape(RoundedRectangle(cornerRadius: 12))
                }
                .padding(20)
            }
            .background(Color(.systemGroupedBackground))
            .navigationTitle("Voice Recorder")
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    if vm.canStop {
                        Button {
                            vm.stopRecording()
                        } label: {
                            Label("Stop", systemImage: "stop.circle.fill")
                        }
                    }
                }
            }
            .task {
                AudioSessionManager.shared.ensureConfiguration()
            }
        }
    }

    // ── Derived helpers ─────────────────────────

    private var stateIcon: String {
        switch state {
        case .idle, .error:    return "microphone.slash"
        case .preparing, .ready: return "cloudarrowhead.up"
        case .recording:       return "waveform.fill"
        case .processing:      return "hammer.pointdown"
        case .completed:       return "checkmark.circle.fill"
        }
    }

    private var stateColor: Color {
        switch state {
        case .recording:      return .green
        case .preparing, .ready: return .blue
        case .processing:     return .orange
        case .completed:      return .green
        default:             return .secondary
        }
    }

    private var stateText: String {
        switch state {
        case .idle:            return "Ready to record"
        case .preparing:       return "Preparing…"
        case .ready:           return "Recording soon"
        case .recording:       return "Recording…"
        case .processing:      return "Finishing…"
        case .completed:       return "File saved"
        case .error:           return "Error: \(errorMessage ?? "")"
        }
    }

    var canStop: Bool   { state.canStop }
    var hasCompleted: Bool { switch state { case .completed: true; default: false } }
}
