## My answer to the user prompt

A simple, maintainable approach is to put recording and file management in an `ObservableObject`, and keep the SwiftUI view responsible for presentation. This example saves each recording in the app’s Documents directory and uses the recorder’s metering data to animate the bars.

Add **Privacy - Microphone Usage Description** (`NSMicrophoneUsageDescription`) to your app’s Info.plist.

```swift
import AVFoundation
import SwiftUI

@MainActor
final class AudioRecorderViewModel: ObservableObject {
    @Published private(set) var isRecording = false
    @Published private(set) var audioPower: Float = -60
    @Published private(set) var savedURL: URL?
    @Published var errorMessage: String?

    private var recorder: AVAudioRecorder?
    private var meterTimer: Timer?

    func startRecording() {
        guard !isRecording else { return }

        AVAudioSession.sharedInstance().requestRecordPermission { [weak self] granted in
            DispatchQueue.main.async {
                guard let self else { return }
                guard granted else {
                    self.errorMessage = "Microphone permission is required to record."
                    return
                }
                self.beginRecording()
            }
        }
    }

    private func beginRecording() {
        do {
            let session = AVAudioSession.sharedInstance()
            try session.setCategory(.record, mode: .default)
            try session.setActive(true)

            let directory = FileManager.default.urls(
                for: .documentDirectory, in: .userDomainMask
            )[0].appendingPathComponent("Recordings", isDirectory: true)
            try FileManager.default.createDirectory(
                at: directory, withIntermediateDirectories: true
            )

            let url = directory
                .appendingPathComponent(UUID().uuidString)
                .appendingPathExtension("m4a")

            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44_100,
                AVNumberOfChannelsKey: 1,
                AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
            ]

            let recorder = try AVAudioRecorder(url: url, settings: settings)
            recorder.isMeteringEnabled = true
            guard recorder.record() else {
                throw NSError(
                    domain: "AudioRecorder",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "The recorder could not start."]
                )
            }

            self.recorder = recorder
            savedURL = url
            isRecording = true
            startMetering()
        } catch {
            errorMessage = error.localizedDescription
        }
    }

    func stopRecording() {
        guard isRecording else { return }

        meterTimer?.invalidate()
        meterTimer = nil
        recorder?.stop()
        recorder = nil
        isRecording = false

        do {
            try AVAudioSession.sharedInstance().setActive(
                false, options: .notifyOthersOnDeactivation
            )
        } catch {
            errorMessage = error.localizedDescription
        }
    }

    private func startMetering() {
        meterTimer?.invalidate()
        meterTimer = Timer.scheduledTimer(withTimeInterval: 0.1, repeats: true) {
            [weak self] _ in
            guard let self, let recorder = self.recorder else { return }
            recorder.updateMeters()
            self.audioPower = recorder.averagePower(forChannel: 0)
        }
    }

    deinit {
        meterTimer?.invalidate()
    }
}

struct VoiceRecorderView: View {
    @StateObject private var viewModel = AudioRecorderViewModel()

    private let barScales: [CGFloat] = [0.45, 0.7, 1.0, 0.7, 0.45]

    private var normalizedPower: CGFloat {
