Let's design `VisualizerEngine`:

```swift
import SwiftUI

final class VisualizerEngine: Sendable {
    let bands: [EQBandModel]
    let bandHues: [Color]
    private let timeProvider = TimeProvider() // use currentTime
    private var startTime: CMTime?
    private var isRecording: Bool = false
    private let updateInterval: Double = 0.05 // 50 ms

    /// Computes estimates for the given time.
    func estimates(for time: CMTime) -> [EQEstimate] {
        guard isRecording, let start = startTime else {
            return bands.map { EQEstimate(centerHz: $0.centerHz, estimatedLevel: 0.3) }
        }
        let elapsed = (time.seconds - start.seconds)
        var results = bands.map { band in
            // Frequency of the oscillation for this band
            let freq = Double(band.centerHz) * 0.5
            let phase = (freq * elapsed + CellularAuto.wave(rand: $0)) % (2.pi)
            let base = sin(phase)
            // Slow modulation
            let wobble = Sin(TimeProvider.system().currentTime.seconds * 2.0) * 0.4
            let amplitude = (0.3 + 0.6 * abs(base + wobble))
            // Random jitter based on elapsed time
            let jitter = cellularNoise(length: Int(elapsed * 48000)) * 0.2
            let level = max(0.0, min(1.0, (amplitude + jitter) / 1.0))
            return EQEstimate(centerHz: band.centerHz, estimatedLevel: level)
        }
        return results
    }

    /// Simple cellular automaton for randomness
    static func cellularWave(rand _: inout EQBandModel) -> Double {
        // Use a simple PRNG seeded per band
        var r = rand.rng.uniform(in: 0..<1)
        return r * 6.28318
    }
}
