```swift
final class MicRecordingPipeline: RecordingPipelineProtocol, Sendable {
    // Exposed for EQ control
    public var eqController: EQController

    let outputQueue = DispatchQueue(label: "pipeline-output", qos: .utility)

    private var engine: AVAudioEngine?
    private var inputNode: AVRecordingInputNode?
    private var writer: AVAudioFileWriter<AVAudioFormatPCMFormat>?

    private let format: AVAudioFormat
    private let targetURL: URL

    init(format: AVAudioFormat, at url: URL) {
        self.format = format
        self.targetURL = url
        eqController = EQController()
    }

    func prepare() throws -> URL {
        guard eqController.effect == nil else { return targetURL }
        let session = AVAudioSession.sharedInstance()

        // Create engine
        do {
            engine = try AVAudioEngine()
        } catch {
            throw PipelineError.engineCreateFailed
        }

        // Input node
        let inputNode = AVRecordingInputNode(source: nil)
        let params = AVAudioNodeParams(
            inputParameters: AVAudioInputParameters(format: format, channels: 1, sampleRate: UInt32(format.sampleRate)),
            outputParameters: nil
        )
        try? inputNode?.configure(with: params)
        self.inputNode = inputNode

        // EQ controller
        do {
            try eqController.initialize(sampleRate: UInt32(format.sampleRate), bandCount: EQ_BAND_COUNT)
        } catch {
            throw PipelineError.setupFailed(error)
        }

        // Create file writer
        writer = AVAudioFileWriter(format: format, at: targetURL)

        // Attach writer to engine output
        guard let engine = engine else { throw PipelineError.notPrepared }
        engine.output.writeFileWriter(writer)!

        // Connect graph
        guard let inp = inputNode, let eq = eqController.effect, let eng = engine else { throw PipelineError.notConnected }
        try eng.connect(inp.to, to: eq.inputPort.from, via: .master)
        try eng.connect(eq.outputPort.to, to: eng.outputNode.to, via: .default)

        return targetURL
    }

    func startRecording(at url: URL) throws {
        guard url == targetURL else { throw PipelineError.invalidURL }
        let session = AVAudioSession.sharedInstance()
        do {
            try session.beginRecording()
        } catch {
            throw PipelineError.startFailed(error)
        }
        // Graph is already connected
    }

    func stopRecording() throws {
        let session = AVAudioSession.sharedInstance()
        try? session.endRecording()

        if let writer = writer {
            // Optionally finalize/close writer
            // writer.close()? // Check if exists
        }

        // Detach nodes
        guard let eq = eqController.effect, let inp = inputNode, let eng = engine else { return }
        try? eng.disconnect(eq.outputPort.to, from: eng.outputNode.to, via: .default)
        try? eng.disconnect(inp.to, from: eq.inputPort.from, via: .master)
        eng.detach(inp)
        engine = nil
        inputNode = nil
        writer = nil
    }
}
```

