extension AVAudioFormat {
    /// Convenience to check if a format is suitable for voice recording
    static var isVoiceRecordingCompatible: Bool {
        // Quick heuristic: 16-bit, 44.1–48 kHz, 1-2 channels
        let sr = common?.sampleRate ?? 0
        return (sr >= 44100 && sr <= 48000) && bitsPerSample == 16 && (channels ?? 1) <= 2
    }
}
