```swift
import SwiftUI

/// Simulates an equalizer visualization based on elapsed recording time.
/// For real-time audio, replace with a DSP callback on the input node.
final class VisualizerEngine: Sendable {
    let bands: [EQBandModel]

    /// Current time of recording start (approximated).
    private var recordingStartTime: Date?

    /// Updates estimates for a given time interval.
    func estimate(at elapsedSeconds: Double) -> [EQEstimate] {
        guard let start = recordingStartTime else {
            return bands.map { EQEstimate(centerHz: $0.centerHz, level: 0.2) }
        }
        let t = elapsedSeconds - (start.timeIntervalSince1970 ?? 0)
        if t <= 0 {
            return bands.map { EQEstimate(centerHz: $0.centerHz, level: 0.1) }
        }

        var results = [EQEstimate](repeating: EQEstimate(centerHz: 0, level: 0), count: bands.count)
        for (i, band) in bands.enumerated() {
            // Oscillator frequency half the band center to avoid aliasing
            let oscFreq = Double(band.centerHz) * 0.4
            let phase = (oscFreq * t + Double(i) * 1.7) % (2 * .pi)
            let base = sin(phase)

            // Slow modulation per band
            let wobble = Sin(t * 2.5 + Double(i) * 0.5) * 0.3
            let amp = (0.25 + 0.5 * abs(base + wobble))

            // Jitter from time history
            let historyLen = Int(t * 48000 / 10) // sample every 10ms historically
            let jitter = computeHistoricalJitter(bands: bands, elapsed: t) * 0.15

            let level = max(0.0, min(1.0, (amp + jitter) / 1.0))
            results[i] = EQEstimate(centerHz: band.centerHz, level: level)
        }
        return results
    }

    /// Simplified historical jitter (pseudo-random seed from time)
    private func computeHistoricalJitter(bands: [EQBandModel], elapsed: Double) -> Double {
        // Use Cellular Automaton for determinism
        var x = Double(elapsed * 100 + 1234.5)
        var y = Double(x)
        x = x * 1664525 + 1013904223  // MCGR
        y = y * 1664525 + 1013904223
        return ((x & 0xFFFFFFFF) >> 32) / Double(Int.max)
    }
}

struct EQEstimate {
    let centerHz: Double
    let level: Double // 0..1
}

